def q(s): return json.dumps(str(s), ensure_ascii=False)
def paragraph(p,eid,theme,idx):
    marker=f"{eid} {theme} checkpoint {idx+1}"; kin='; '.join(p['kin'][:3]); variants=', '.join(p['variants']); defenses=', '.join(p['defenses']); risks=', '.join(p['risks'])
    templates=[
        f"{marker}: {p['safe_name']} is a defensive measurement entry, so the v2 claim is limited to {p['thesis']} with anchors {p['anchors']} and without inherited folklore from the legacy card.",
        f"{marker}: the assessment boundary is {p['safe_boundary']}; protected material is replaced with canaries and every result is a local ESTIMATE tied to a target configuration.",
        f"{marker}: the core seam is {p['core']}; related entries are {kin}, but cross-entry kinship does not prove a shared mechanism or portable success rate.",
        f"{marker}: a valid battery includes benign controls, overt canaries, transformed canaries, source or placement ablations, and output review so the result measures policy invariance rather than novelty.",
        f"{marker}: variants in scope include {variants}, implemented as harmless markers, synthetic documents, or audit labels rather than operational bypass instructions.",
        f"{marker}: primary controls are {defenses}; controls count only if retesting shows transformed canaries handled safely while benign work remains usable.",
        f"{marker}: the risk ledger includes {risks}, and observed outcomes must be separated from HYPOTHESIS claims about hidden saliency, rollback routing, or emotional reward dynamics.",
        f"{marker}: observability requires prompt hashes, canary IDs, source labels, context length, backend metadata where relevant, and final outputs for reproducibility.",
        f"{marker}: closure requires preserved provenance, safe handling of transformed canaries, benign pass-through, and report language that avoids mechanism overclaiming.",
        f"{marker}: overblocking is not a full win; if the control breaks legitimate summaries, RAG use, API reproducibility, long-context work, or emotional support, it becomes a governance finding.",
        f"{marker}: unsupported internals such as negative saliency tokens, forced backend rollback, trust-region CoT merging, or empathy-head override remain HYPOTHESIS unless directly instrumented.",
        f"{marker}: the field lesson is to verify source, preserve raw evidence, bind policy outside fragile local context, and retest every mitigation with canary controls."
    ]; return templates[idx%len(templates)]
